async function model(id){if(!cache.has(id))cache.set(id,loader.loadAsync(`${base}${id}.glb`).then(g=>{g.scene.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});return g.scene;}));return cache.get(id);}
