async function enableAudio(){if(!audioContext){try{audioContext=new AudioContext();await audioContext.resume();for(const[name,bytes]of sounds){if(bytes instanceof ArrayBuffer)sounds.set(name,await audioContext.decodeAudioData(bytes.slice(0)));}}catch{soundOn=false;$('#sound').checked=false;}}else await audioContext.resume();}
function sound(name,volume=.65){const buffer=sounds.get(name);if(!soundOn||!audioContext||!buffer||buffer instanceof ArrayBuffer)return;const source=audioContext.createBufferSource(),gain=audioContext.createGain();source.buffer=buffer;gain.gain.value=volume;source.connect(gain);gain.connect(audioContext.destination);source.start();}
