function enter(resume=false){if(resume){const data=loadSave();if(!data||!core.load(data)){showMessage('Checkpoint is incompatible or corrupt. Start a new operation.');$('#continue').textContent='Checkpoint unavailable — start a new operation';$('#continue').disabled=true;return;}}else core.api.dh_new(Number($('#difficulty').value));running=true;menuPhase=-1;lastMessage=0;savedSerial=core.get(22);yaw=core.get(3);pitch=core.get(4);clearInput();$('#front-menu').hidden=true;$('#hud').hidden=false;$('#pause-overlay').hidden=true;camera.fov=68;camera.updateProjectionMatrix();enableAudio();showMessage('Culebra ready. The cargo manifest is beside the crates. Watch the patrols.');captureMouse();}
function updateOverlay(phase){if(phase===menuPhase)return;menuPhase=phase;if(phase===0){$('#pause-overlay').hidden=true;return;}clearInput();exitMouse();$('#pause-overlay').hidden=false;$('#resume').hidden=phase!==1;$('#retry').hidden=phase===3;$('#pause-title').textContent=phase===2?'Operation interrupted.':phase===3?'Evidence secured.':'Hold your position.';$('#pause-copy').textContent=phase===2?'You were overwhelmed. Retry from the last recovered record, or start a fresh approach.':phase===3?'The records are safe. La Aduana’s signal is silent. You made it back to the jetty. This completes the current combat slice.':'The operation is paused. Checkpoints save when you recover evidence or disable the signal.';$('#debrief').textContent=`${Math.floor(core.get(16)/60)}m ${Math.floor(core.get(16)%60)}s in the field · ${core.get(13)} guards defeated · ${[0,1,2].filter(i=>core.get(12)&(1<<i)).length}/3 objectives`;}
function pause(){if(!running)return;core.api.dh_pause();updateOverlay(core.get(11));}
function restart(){core.api.dh_new(Number($('#difficulty').value));yaw=0;pitch=0;savedSerial=0;lastMessage=0;menuPhase=-1;clearInput();updateOverlay(0);showMessage('Fresh operation. Your first objective is the cargo manifest.');captureMouse();}
