function back(){running=false;clearInput();exitMouse();$('#hud').hidden=true;$('#pause-overlay').hidden=true;$('#front-menu').hidden=false;frameWorld();}
$('#begin').onclick=()=>enter(false);$('#continue').onclick=()=>enter(true);$('#pause-button').onclick=pause;$('#resume').onclick=()=>{core.api.dh_pause();updateOverlay(core.get(11));captureMouse();};$('#retry').onclick=retry;$('#restart').onclick=restart;$('#return-menu').onclick=back;
$('#sound').onchange=e=>{soundOn=e.target.checked;if(soundOn)enableAudio();};$('#safe-effects').onchange=e=>reduced=e.target.checked;
addEventListener('keydown',e=>{if(!running)return;if(['Escape','KeyW','KeyA','KeyS','KeyD','KeyR','KeyE','KeyH','KeyF','Space','ControlLeft','ShiftLeft','Digit1','Digit2','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&!e.repeat){pause();return;}if(core.get(11)===0)keys.add(e.code);});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{clearInput();if(running&&core.get(11)===0){core.api.dh_pause();updateOverlay(1);}});
renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('pointerdown',e=>{if(!running||core.get(11))return;captureMouse();if(e.button===0)buttons|=B.FIRE;if(e.button===2)buttons|=B.AIM;drag={x:e.clientX,y:e.clientY};});addEventListener('pointerup',e=>{if(e.button===0)buttons&=~B.FIRE;if(e.button===2)buttons&=~B.AIM;drag=null;});addEventListener('pointercancel',()=>{buttons=0;drag=null;});
addEventListener('mousemove',e=>{if(!running||core?.get(11)!==0)return;let dx=0,dy=0;if(document.pointerLockElement===renderer.domElement){if(ignoreRelativeMove){ignoreRelativeMove=false;return;}if(performance.now()<mouseWarmupUntil||Math.abs(e.movementX)>200||Math.abs(e.movementY)>200)return;dx=e.movementX;dy=e.movementY;}else if(drag){dx=e.clientX-drag.x;dy=e.clientY-drag.y;drag={x:e.clientX,y:e.clientY};}const sensitivity=(buttons&B.AIM)?.0012:.0023;yaw-=dx*sensitivity;pitch=T.MathUtils.clamp(pitch-dy*sensitivity,-1.35,1.35);});
