function input(){let mask=buttons;if(keys.has('KeyF'))mask|=B.FIRE;if(keys.has('ShiftLeft')||keys.has('ShiftRight'))mask|=B.SPRINT;if(keys.has('ControlLeft')||keys.has('KeyC'))mask|=B.CROUCH;if(keys.has('KeyR'))mask|=B.RELOAD;if(keys.has('KeyE'))mask|=B.INTERACT;if(keys.has('KeyH'))mask|=B.HEAL;if(keys.has('Space'))mask|=B.JUMP;if(keys.has('Digit1'))mask|=B.PISTOL;if(keys.has('Digit2'))mask|=B.RIFLE;return mask;}
function effect(event){const[type,x,y,z,tx,ty,tz,value]=event;if(type===1||type===3){const start=type===1?new T.Vector3(.19,-.18,-.48).applyMatrix4(camera.matrixWorld):new T.Vector3(x,y,z);const geo=new T.BufferGeometry().setFromPoints([start,new T.Vector3(tx,ty,tz)]);const material=new T.LineBasicMaterial({color:type===1?0xe8dc9f:0xdb9c66,transparent:true,opacity:.7,depthWrite:false});const line=new T.Line(geo,material);scene.add(line);effects.push({object:line,ttl:type===1?.055:.11,max:type===1?.055:.11});if(type===1){recoil=.045;sound(value?'rifle':'shot',.7);}else sound('rifle',.13);}if(type===2){const dot=new T.Mesh(new T.SphereGeometry(value?.035:.022,6,4),new T.MeshBasicMaterial({color:value?0xd9ba77:0xc6c3a3,transparent:true}));dot.position.set(x,y,z);scene.add(dot);effects.push({object:dot,ttl:.16,max:.16});if(value)sound('impact',.5);}if(type===7)sound('reload',.5);if(type===6)sound('heal',.5);if(type===4||type===5)sound('objective',.55);if(type===8)damage=.45;}
