async function inspectAsset(id){if(displayAsset)scene.remove(displayAsset);displayAsset=(await model(id)).clone();displayAsset.visible=true;scene.add(displayAsset);renderer.shadowMap.needsUpdate=true;world.visible=false;water.visible=false;studioFloor.visible=true;enemies.forEach(e=>e.visible=false);pistol.visible=rifle.visible=false;running=false;$('#front-menu').hidden=$('#hud').hidden=$('#pause-overlay').hidden=true;const box=new T.Box3().setFromObject(displayAsset),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),extent=Math.max(size.x,size.y,size.z);studioFloor.position.y=box.min.y-.012;if(!id.startsWith('L_')){Object.assign(sun.shadow.camera,{left:-extent*2,right:extent*2,top:extent*2,bottom:-extent*2});sun.shadow.camera.updateProjectionMatrix();}else{Object.assign(sun.shadow.camera,{left:-40,right:40,top:40,bottom:-40});sun.shadow.camera.updateProjectionMatrix();}camera.fov=43;camera.position.copy(center).add(new T.Vector3(1.35,.75,1.7).multiplyScalar(extent*.98));camera.lookAt(center);if(id.startsWith('L_')){water.visible=true;studioFloor.visible=false;camera.position.set(37,23,42);camera.lookAt(-2,2,-6);}camera.updateProjectionMatrix();}
async function boot(){try{
 const bytes=await fetch('/slice-core.wasm').then(r=>{if(!r.ok)throw Error('Shared simulation missing. Run npm run slice:core.');return r.arrayBuffer();});core=await createCore(bytes);
 $('#load-status').textContent='Preparing the coast, equipment and sentries…';
 const [map,guard,p,r]=await Promise.all([model('L_PuertoChico_Combat'),model('SM_Cosecha_Sentry_01'),model('SM_Culebra_W01'),model('SM_Libertad_W05')]);world=map;scene.add(world);pistol=p.clone();rifle=r.clone();for(const gun of[pistol,rifle]){gun.traverse(o=>{if(o.isMesh){o.castShadow=false;o.receiveShadow=false;}});camera.add(gun);gun.scale.setScalar(1.25);}for(let i=0;i<8;i++){const g=guard.clone();g.traverse(o=>{if(o.isMesh)o.castShadow=false;});scene.add(g);enemies.push(g);}
 for(const name of['shot','rifle','impact','reload','heal','objective'])sounds.set(name,await fetch(`${base}audio/${name}.wav`).then(r=>r.arrayBuffer()));
 frameWorld();$('#loading').hidden=true;$('#front-menu').hidden=false;$('#continue').disabled=!loadSave();
 const params=new URLSearchParams(location.search);if(params.get('render'))await inspectAsset(params.get('render'));
 if(params.has('qa'))window.__combat={freeze:()=>renderer.setAnimationLoop(null),core,state:()=>core.state(),start:()=>enter(false),pause,retry,restart,back,inspectAsset,inspectionState:()=>({id:displayAsset?.name,visible:displayAsset?.visible,worldVisible:world.visible}),teleport:(x,z)=>core.api.dh_debug_position(x,z),enemy:(i,x,z,y)=>core.api.dh_debug_enemy(i,x,z,y),aim:(y,p)=>{yaw=y;pitch=p;},capture:()=>{renderer.render(scene,camera);return renderer.domElement.toDataURL('image/png');}};
 window.__combatReady=true;
 renderer.setAnimationLoop(time=>{const dt=Math.min((time-lastTime)/1000||0,.08);lastTime=time;advance(dt);renderer.render(scene,camera);});
 }catch(error){console.error(error);$('#load-status').textContent=`Unable to start: ${error.message}`;}}
boot();
